import {questionFields,collectAnswers,briefDetailsHTML} from './brief-details.mjs';
import {seeds,escapeHTML as e,safeURL} from './domain.mjs';
import {initializeCollaboration,sendMessage,proposeTerms,acceptTerms,agreed,submitWork as recordSubmission,requestChanges,approveWork} from './collaboration.mjs';
import {workspaceHTML,roomHTML,termsForm} from './room.mjs';
import {storefront} from './art.mjs';
import {aiState,enableAI,generateBrief,reviewCaption,observeAI} from './ai.mjs';
const key='localperks-v1';
let state={campaigns:structuredClone(seeds),applications:[],saved:[]};
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&Array.isArray(saved.campaigns)&&Array.isArray(saved.applications)&&Array.isArray(saved.saved))state=saved;}catch{}
state.applications=state.applications.map(initializeCollaboration);
let roomId=null;
let role='creator',view='dashboard',category='All',reward='All rewards',city='All cities',search='',savedOnly=false,draft=null;
let partners={backboard:false,shared:false};
const $=s=>document.querySelector(s),modal=$('#modal'),main=$('#main');
const icon='↗';
function persist(){try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('Browser storage is full. Download your data from Settings before closing.');}updateCount();}
const ownApplications=()=>state.applications.filter(a=>!a.sample&&a.id!=='sample-negotiation');
function updateCount(){const count=ownApplications().length;$('#workspace-count').textContent=count?`(${count})`:'';}
let toastTimer;
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4200);}
function openModal(title,content){document.body.classList.remove('sidebar-open');syncSidebar();$('#modal-content').innerHTML=`<div class="modal-inner"><div class="modal-top"><h2>${e(title)}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${content}</div>`;if(!modal.open)modal.showModal();modal.scrollTop=0;}
function card(c){return `<article class="card"><div class="card-image">${storefront(c.art,c.color)}<span class="card-label">${e(c.category)}</span><button class="bookmark ${state.saved.includes(c.id)?'saved':''}" data-action="save" data-id="${e(c.id)}" aria-label="${state.saved.includes(c.id)?'Unsave':'Save'} ${e(c.title)}" aria-pressed="${state.saved.includes(c.id)}">${state.saved.includes(c.id)?'♥':'♡'}</button></div><div class="card-body"><div class="business-line"><span class="business-icon">⌂</span>${e(c.business)}<span>·</span>${e(c.city)}</div><h3>${e(c.title)}</h3><p class="card-desc">${e(c.description)}</p><div class="tags"><span class="tag">${e(c.platform)}</span><span class="tag">${c.deliverables.length} deliverables</span><span class="tag">${c.sample?'Sample opportunity':'Your opportunity'}</span></div><div class="card-bottom"><div class="reward">${e(c.reward)}<small>Agreed reward · no platform payout</small></div><button class="arrow-button" data-action="details" data-id="${e(c.id)}" aria-label="View ${e(c.title)}">${icon}</button></div></div></article>`;}
function filtered(){return state.campaigns.filter(c=>(view!=='campaigns'||!c.sample)&&(category==='All'||c.category===category)&&(reward==='All rewards'||c.rewardType===reward)&&(city==='All cities'||c.city===city)&&(!savedOnly||state.saved.includes(c.id))&&`${c.title} ${c.business} ${c.city} ${c.description}`.toLowerCase().includes(search.toLowerCase()));}
function renderCards(){const list=filtered();$('#cards').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><h3>No opportunities here yet.</h3><p>Try a different city or category, or create your first opportunity.</p><button class="button" data-action="new">Create an opportunity ${icon}</button></div>`;$('#result-count').textContent=`${list.length} ${list.length===1?'opportunity':'opportunities'}${view==='saved'?' saved':''}`;}
function roleSwitch(){return `<div class="role-switch"><button class="${role==='creator'?'selected':''}" aria-pressed="${role==='creator'}" data-role="creator">✧ I’m a creator</button><button class="${role==='business'?'selected':''}" aria-pressed="${role==='business'}" data-role="business">⌂ I’m a business</button></div>`;}
function render(){renderShell();updateCount();if(view==='dashboard'||view==='gemma'){renderDashboard();return;}if(view==='workspace'){renderWorkspace();return;}if(view==='room'){renderRoom();return;}
main.innerHTML=`<section id="opportunities"><div class="section-title"><div><h2>${view==='campaigns'?'Your campaigns.':view==='saved'?'Saved for later.':'Your neighborhood, your next opportunity.'}</h2><p>${view==='campaigns'?'Manage the opportunities you’ve created in this workspace.':view==='saved'?'Pick up where inspiration found you.':'Discover small businesses looking for someone just like you.'}</p></div><button class="button ${role==='business'?'primary':'secondary'}" data-action="new">Create an opportunity <span>+</span></button></div><div class="filters"><div class="search"><span aria-hidden="true">⌕</span><input id="search" type="search" aria-label="Search opportunities" placeholder="Search businesses, neighborhoods, or ideas…" value="${e(search)}"></div><select class="filter" id="city" aria-label="Filter by city">${['All cities',...new Set(state.campaigns.map(c=>c.city))].map(x=>`<option ${city===x?'selected':''}>${e(x)}</option>`).join('')}</select><select class="filter" id="reward" aria-label="Filter by reward">${['All rewards','Cash + perks','Cash','Perks'].map(x=>`<option ${reward===x?'selected':''}>${e(x)}</option>`).join('')}</select><div class="filter-wrap">${['All','Food & drink','Shops & makers','Wellness'].map(x=>`<button class="chip ${category===x?'active':''}" data-category="${e(x)}">${e(x)}</button>`).join('')}</div></div><div class="results-line"><span id="result-count"></span>${role==='creator'?`<button class="text-button" data-action="saved">${savedOnly?'Show all opportunities':'♡ Saved opportunities'}</button>`:''}</div><div class="grid" id="cards"></div></section><section class="local-strip"><div><h3>Your business. Their creativity. A good match.</h3><p>Tell us what you’re planning. Turn it into a brief creators can act on.</p></div><button class="button" data-action="new">Create your first opportunity ${icon}</button></section>`;renderCards();}
function renderShell(){
 $('#top-role-switch').innerHTML=roleSwitch();$('#role-context').textContent=role==='business'?'Business workspace':'Creator workspace';
 const target=role==='business'?'campaigns':'explore',label=role==='business'?'My campaigns':'Find opportunities';
 $('#opportunities-nav').dataset.view=target;$('#opportunities-label').textContent=label;$('#opportunities-nav').setAttribute('aria-label',label);$('#opportunities-nav').title=label;$('#saved-nav').hidden=role==='business';
 document.querySelectorAll('[data-view]').forEach(n=>{const active=n.dataset.view===(view==='room'?'workspace':view);n.classList.toggle('active',active);if(active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});
}
function navigate(next){modal.close();view=next;savedOnly=next==='saved';document.body.classList.remove('sidebar-open');syncSidebar();render();window.scrollTo({top:0,behavior:'instant'});}
function syncSidebar(){const mobile=matchMedia('(max-width:850px)').matches,expanded=mobile?document.body.classList.contains('sidebar-open'):!document.body.classList.contains('sidebar-collapsed');document.querySelectorAll('[data-action="toggle-sidebar"]').forEach(b=>{b.setAttribute('aria-expanded',String(expanded));b.setAttribute('aria-label',expanded?'Collapse navigation':'Open navigation');b.title=expanded?'Collapse navigation':'Open navigation';});$('#collapse-icon').textContent=expanded?'⇤':'⇥';}
function renderDashboard(){const apps=ownApplications(),campaigns=state.campaigns.filter(c=>!c.sample),pending=apps.filter(a=>a.status==='Applied'),reviewing=apps.filter(a=>a.status==='Work submitted'),active=apps.filter(a=>['In progress','Changes requested'].includes(a.status));
 const metrics=role==='business'?[[campaigns.length,'Your campaigns'],[pending.length,'Proposals to review'],[reviewing.length,'Work to review']]:[[apps.length,'Your applications'],[active.length,'In progress'],[state.saved.length,'Saved opportunities']];
 main.innerHTML=`<div class="dashboard-heading"><div><div class="eyebrow"><span></span>${role==='business'?'BUSINESS DASHBOARD':'CREATOR DASHBOARD'}</div><h2>${view==='gemma'?'Your Gemma studio.':role==='business'?'Bring your next campaign to life.':'Good work, around the corner.'}</h2><p>${role==='business'?'Create a brief, review creator proposals, and keep collaborations moving.':'Find opportunities, track your applications, and get your content ready.'}</p></div><button class="button secondary" data-view="${role==='business'?'campaigns':'explore'}">${role==='business'?'View my campaigns':'Find opportunities'} ↗</button></div><section class="gemma-home" aria-labelledby="gemma-heading"><div class="eyebrow"><span></span>Your local collaboration, powered by Gemma</div><h1 id="gemma-heading">${role==='business'?'A neighborhood idea.<br><em>A collaboration in the making.</em>':'Your next local collab.<br><em>Make it your own.</em>'}</h1><p>${role==='business'?'Turn your next promotion into a brief local creators can act on.':'Check your caption against the brief before sending it to the business.'}</p><div class="gemma-composer"><div class="gemma-tools">${role==='business'?'<span class="tool-selected">✧ Write a brief</span><button type="button" data-action="caption-check">Review a caption ↗</button>':'<span class="tool-selected">✧ Review a caption</span><button type="button" data-action="new">Write a brief ↗</button>'}</div><form id="${role==='business'?'idea-start-form':'caption-start-form'}"><label for="starter-idea">${role==='business'?'What would you like a local creator to promote?':'What caption are you working on?'}</label><textarea id="starter-idea" name="idea" maxlength="${role==='business'?1500:4000}" required placeholder="${role==='business'?'Our café is launching a fall menu. We’d love a local creator to film a cozy morning visit…':'Paid partnership with Sunday Coffee. A slow morning, a maple latte, and a new favorite neighborhood spot…'}"></textarea><div class="gemma-composer-bottom"><span>${role==='business'?'Gemma drafts. You edit and approve.':'Gemma suggests. Your voice stays yours.'}</span><button class="button primary" type="submit">${role==='business'?'Build my brief with Gemma ↗':'Check my caption with Gemma ↗'}</button></div></form></div><div class="gemma-home-foot"><span>Hosted AI · no model download</span><button class="text-button" data-action="browse">Or explore local opportunities ↓</button></div></section>${view==='dashboard'?`<div class="dashboard-metrics">${metrics.map(([value,label])=>`<div><strong>${value}</strong><span>${label}</span></div>`).join('')}</div>`:''}<div class="dashboard-next"><div><h3>${role==='business'?'Keep your collaborations moving.':'From a first hello to a finished post.'}</h3><p>${role==='business'?'Review proposals, negotiate terms, and approve completed work.':'Check messages, agree on terms, and submit your work.'}</p></div><button class="button secondary" data-view="workspace">Open collaborations ↗</button></div>`;
}
function details(id){const c=state.campaigns.find(x=>x.id===id);if(!c)return;const applied=ownApplications().some(x=>x.campaignId===id);openModal(c.title,`<div class="modal-image">${storefront(c.art,c.color)}</div><p class="modal-intro">${e(c.business)} · ${e(c.city)}${c.sample?' · Sample business':''}</p><p class="modal-intro">${e(c.description)}</p><div class="details-grid"><div><small>REWARD</small>${e(c.reward)}</div><div><small>PLATFORM</small>${e(c.platform)}</div><div><small>DEADLINE</small>${e(c.deadline)}</div></div><h3>What you’ll create</h3><ul class="detail-list">${c.deliverables.map(x=>`<li>${e(x)}</li>`).join('')}</ul>${briefDetailsHTML(c.clarificationAnswers)}<div class="callout">Agree on the scope, reward, content usage, and timing with the business before starting. This prototype tracks the agreement; it does not hold funds, send payments, or verify reach.</div><div class="actions">${role==='business'?`<button class="button secondary" data-action="workspace">Manage collaborations</button>`:`<button class="button primary" data-action="apply" data-id="${e(id)}" ${applied?'disabled':''}>${applied?'Application saved':'Apply for this collaboration'} ${icon}</button>`}</div>`);}
function apply(id){const c=state.campaigns.find(x=>x.id===id);openModal('Make your introduction.',`<p class="modal-intro">Apply to ${e(c.business)} for “${e(c.title)}”. Your application is saved in this browser for the demo.</p><form id="apply-form" data-id="${e(id)}"><div class="form-grid"><div><label for="creator">Your name</label><input id="creator" name="creator" required maxlength="80" placeholder="Alex Rivera"></div><div><label for="handle">Creator handle</label><input id="handle" name="handle" required maxlength="80" placeholder="@alexaroundtown"></div></div><label for="pitch">What would you create?</label><textarea id="pitch" name="pitch" required maxlength="1200" placeholder="I’d love to make a neighborhood guide featuring your business…"></textarea><label class="check-row"><input type="checkbox" required>I understand the listed deliverables and reward. Final terms still need agreement with the business.</label><div class="actions"><button class="button primary" type="submit">Save application ${icon}</button></div></form>`);}
function renderWorkspace(){main.innerHTML=workspaceHTML(state,role,()=> '');}
function renderRoom(){const a=state.applications.find(x=>x.id===roomId),c=state.campaigns.find(x=>x.id===a?.campaignId);if(!a||!c){view='workspace';renderWorkspace();return;}main.innerHTML=roomHTML(a,c,role,()=> '');}
function replaceApplication(id,next){const index=state.applications.findIndex(x=>x.id===id);if(index<0)throw new Error('Collaboration not found.');state.applications[index]=next;persist();}
function newBrief(idea=''){draft=null;openModal('Draft your brief with Gemma.',`<p class="modal-intro">Fill in your promotion, reward, and deadline, then choose Draft with Gemma below. Gemma writes a title, description, and deliverables for you to review. No download or setup needed.</p><form id="brief-form"><div class="form-grid"><div><label for="business">Business name</label><input id="business" name="business" required maxlength="80" placeholder="Your neighborhood business"></div><div><label for="location">City & state</label><input id="location" name="city" required maxlength="80" value="Chicago, IL"></div></div><label for="idea">What would you like to promote?</label><textarea id="idea" name="idea" required maxlength="1500" placeholder="We’re a small café launching a new fall menu. We’d love a local creator to visit, try a drink, and share their honest experience…">${e(idea)}</textarea><div class="form-grid"><div><label for="compensation">Exact reward</label><input id="compensation" name="reward" required maxlength="100" placeholder="$75 + two drinks"></div><div><label for="deadline">Work due</label><input id="deadline" name="deadline" type="date" min="${new Date().toLocaleDateString('en-CA')}" required></div><div><label for="platform">Platform</label><select id="platform" name="platform"><option>Instagram</option><option>TikTok</option><option>YouTube</option></select></div><div><label for="category">Category</label><select id="category" name="category"><option>Food & drink</option><option>Shops & makers</option><option>Wellness</option></select></div><div><label for="reward-type">Reward type</label><select id="reward-type" name="rewardType"><option>Cash + perks</option><option>Cash</option><option>Perks</option></select></div></div><div id="brief-ai" class="callout lavender">✧ Gemma: ${aiState.ready?'Connected and ready to draft.':aiState.failed?'Connection unavailable. Retry from Settings or use the manual template.':'Connecting automatically. No model download is needed.'}</div><div id="brief-status" class="ai-status" role="status"></div><div class="actions"><button class="button secondary" type="submit" name="mode" value="manual">Use manual template</button><button class="button primary" type="submit" name="mode" value="ai">✧ Draft with Gemma</button></div></form>`);}
function editDraft(){openModal('Make the brief yours.',`<p class="modal-intro">${draft.ai?'Drafted by hosted Gemma.':'Manual template — no AI was used.'} Review every detail before adding this opportunity.</p><form id="publish-form"><label for="title">Opportunity title</label><input id="title" name="title" required maxlength="120" value="${e(draft.title)}"><label for="description">Description</label><textarea id="description" name="description" required maxlength="2000">${e(draft.description)}</textarea><label for="deliverables">Deliverables — one per line</label><textarea id="deliverables" name="deliverables" required maxlength="2400">${e(draft.deliverables.join('\n'))}</textarea>${questionFields(draft.questions)}<div class="mini-panel">${e(draft.business)} · ${e(draft.city)}\nReward: ${e(draft.reward)}\nDue: ${e(draft.deadline)} · ${e(draft.platform)}</div><label class="check-row"><input type="checkbox" required>I’ve checked the reward, deliverables, and deadline. This adds an opportunity to this browser’s demo workspace.</label><div class="actions"><button class="button primary" type="submit">Add opportunity ${icon}</button></div></form>`);}
function captionCheck(caption=''){openModal('Review a caption with Gemma.',`<p class="modal-intro">Check written content against your campaign requirements. Gemma suggests improvements; you make the final call.</p><form id="caption-check-form"><label for="check-deliverables">Campaign requirements — one per line</label><textarea id="check-deliverables" name="deliverables" required maxlength="2400" placeholder="Mention the fall menu and café location.&#10;Clearly disclose the paid collaboration."></textarea><label for="check-caption">Caption to review</label><textarea id="check-caption" name="caption" required maxlength="4000" placeholder="Paste your draft caption here…">${e(caption)}</textarea><p class="form-hint">Only these requirements and your caption are sent to hosted Gemma. Linked images and videos are not inspected.</p><div id="caption-status" class="ai-status" role="status"></div><div id="caption-result" class="review-text" aria-live="polite"></div><div class="actions"><button class="button primary" type="submit">✧ Review caption with Gemma</button></div></form>`);}
function settings(){openModal('Settings',`<p class="modal-intro">Gemma runs through your hosted Ollama connection. Draft campaign briefs and review caption text without downloading a model or needing a special browser.</p><p class="ai-status" id="ai-status" role="status">${e(aiState.message)}</p>${aiState.failed?'<div class="actions"><button class="button secondary" data-action="enable-ai">Check AI connection</button></div>':''}<hr class="divider"><h3>What gets sent?</h3><p class="form-hint">When you choose Draft with Gemma, the entered campaign details go to the configured Ollama provider. When you choose Review caption with Gemma, the agreed deliverables and caption go to the configured Ollama provider. Browsing and negotiating do not send your conversation to the model. Ollama Cloud says it does not use cloud prompts or responses to train models. <a href="https://ollama.com/privacy" target="_blank" rel="noopener">Provider data terms</a>.</p><hr class="divider"><h3>Campaign memory</h3><p class="form-hint">Backboard is optional and ${partners.backboard?'connected':'disabled'}. Conversation and agreement history already work without it.</p>${partners.backboard?'<button class="button secondary" data-action="memory">Open campaign memory</button>':''}<hr class="divider"><h3>Your demo workspace</h3><p class="form-hint">Sample listings are fictional. Messages, terms, acknowledgments, submitted work, and statuses stay in this browser. Role switching lets you try both sides; shared authenticated accounts are not connected yet. Rewards are delivered outside LocalPerks.</p><p class="form-hint">Download a JSON copy of your opportunities and collaborations for your records. This is optional; your work saves automatically in this browser.</p><div class="actions"><button class="button secondary" data-action="export">Download your data ↓</button><button class="text-button" data-action="reset">Reset sample workspace</button></div><p class="form-hint"><a href="https://docs.ollama.com/cloud" target="_blank" rel="noopener">About hosted Gemma</a></p>`);}
function about(){openModal('Every good collaboration is a conversation.',`<ol class="detail-list"><li><strong>Introduce:</strong> a creator sends a proposal with their idea.</li><li><strong>Discuss:</strong> both sides ask questions, share recommendations, and refine the approach.</li><li><strong>Agree:</strong> propose deliverables, reward, deadline, content usage, and revision rounds. Both sides accept the same version.</li><li><strong>Create:</strong> the creator submits work against the accepted agreement.</li><li><strong>Review:</strong> the business requests changes within the agreed rounds or approves the work.</li><li><strong>Reward:</strong> the business delivers the reward following the agreed timing.</li></ol><div class="callout lavender">Try both sides: send an application, open the collaboration, and switch roles to negotiate and accept terms. A revised agreement always needs fresh acceptance from both sides.</div><p class="form-hint">Hosted AI is built in. It can draft briefs and review submitted caption text, but it cannot inspect linked media, verify performance, or approve payments.</p><div class="actions"><button class="button primary" data-action="close">Explore opportunities ↗</button></div>`);}
function submitWork(id){openModal('Send your work for review.',`<p class="modal-intro">This submission is linked to the latest agreement accepted by both sides. Include a viewable link and the exact caption.</p><form id="work-form" data-id="${e(id)}"><label for="work-url">Work or draft link</label><input id="work-url" type="url" name="submission" required placeholder="https://…"><label for="caption">Caption or written content</label><textarea id="caption" name="caption" maxlength="4000" required placeholder="Paste the caption for the business to review."></textarea><p class="form-hint">The business reviews the linked work. AI can only review the text entered here.</p><div class="actions"><button class="button primary">Submit work ↗</button></div></form>`);}
async function memory(){openModal('A memory for your campaign.',`<p class="modal-intro">Save campaign context and keep a conversation with Backboard. Use business-approved details; text entered here is sent to Backboard when you submit.</p><form id="memory-form"><label for="memory-campaign">Campaign</label><select id="memory-campaign" name="campaignId">${state.campaigns.map(c=>`<option value="${e(c.id)}">${e(c.business)} — ${e(c.title)}</option>`).join('')}</select><label for="memory-question">What would you like to remember or ask?</label><textarea id="memory-question" name="question" required maxlength="2000" placeholder="Remember that we prefer a relaxed tone. What should we clarify before accepting a creator?"></textarea><div id="memory-status" class="ai-status" role="status"></div><div id="memory-result" class="review-text"></div><div class="actions"><button class="button primary" ${!partners.backboard?'disabled':''}>Ask campaign memory ${icon}</button></div></form>${!partners.backboard?'<p class="form-hint">Connect Backboard on the Render server to enable this feature. No simulated answers are displayed.</p>':''}`);}
document.addEventListener('click',async event=>{
 const b=event.target.closest('button');if(!b)return;
 if(b.dataset.role){role=b.dataset.role;if(['saved','explore','campaigns'].includes(view)){view=role==='business'?'campaigns':'explore';savedOnly=false;}render();return;}
 if(b.dataset.view){navigate(b.dataset.view);return;}
 if(b.dataset.category){category=b.dataset.category;render();return;}
 const action=b.dataset.action,id=b.dataset.id;
 if(action==='toggle-sidebar'){document.body.classList.toggle(matchMedia('(max-width:850px)').matches?'sidebar-open':'sidebar-collapsed');syncSidebar();return;}
 if(action==='close-sidebar'){document.body.classList.remove('sidebar-open');syncSidebar();return;}
 if(action==='close'){modal.close();return;}
 if(action==='caption-check')return captionCheck();
 if(action==='about')return about();if(action==='settings')return settings();if(action==='memory')return memory();
 if(action==='sample-room'){let sample=state.applications.find(x=>x.id==='sample-negotiation');if(!sample){const c=state.campaigns.find(x=>x.id==='coffee')||state.campaigns[0];sample=initializeCollaboration({id:'sample-negotiation',campaignId:c.id,creator:'Alex Rivera (sample)',handle:'@alexaroundtown',pitch:'I’d like to make an honest neighborhood café Reel showing my visit and my order.',sample:true,createdAt:new Date().toISOString()});sample=sendMessage(sample,'business','I like your idea. Could you include the café location, clear disclosure, and one round of revisions?');const terms={deliverables:c.deliverables.join('\n'),reward:c.reward,deadline:c.deadline,usageRights:'Creator retains ownership. One organic reshare with credit for 30 days. No paid advertising rights.',paymentTiming:'Business delivers the reward directly within 7 days of final approval.',approvalProcess:'Business reviews the submitted content against the agreed deliverables.',revisions:1,note:'A starting proposal for our collaboration.'};sample=proposeTerms(sample,'business',terms);sample=sendMessage(sample,'creator','That works for the concept. For filming, editing, and one revision, could we make the reward $100 plus coffee?');sample=proposeTerms(sample,'creator',{...terms,reward:'$100 + coffee',note:'The updated rate includes filming, editing, and one revision round.'});sample=acceptTerms(sample,'creator',2);state.applications.push(sample);persist();}roomId=sample.id;view='room';role='business';render();return;}
 if(action==='open-room'){roomId=id;view='room';render();return;}
 if(action==='propose-terms'){const a=state.applications.find(x=>x.id===id),c=state.campaigns.find(x=>x.id===a.campaignId);return openModal(a.terms?'Propose a new agreement.':'Put the details on paper.',termsForm(a,c));}
 if(action==='accept-terms'){const a=state.applications.find(x=>x.id===id),t=a.terms;return openModal(`Accept agreement v${t.version}?`,`<p class="modal-intro">You are accepting as the ${e(role)}. Review the complete agreement in the collaboration before confirming.</p><div class="mini-panel">Deliverables: ${e(t.deliverables)}\nReward: ${e(t.reward)}\nDeadline: ${e(t.deadline)}\nContent usage: ${e(t.usageRights)}\nReward delivery: ${e(t.paymentTiming)}\nReview process: ${e(t.approvalProcess)}\nIncluded revisions: ${t.revisions}</div><form id="accept-form" data-id="${e(id)}" data-version="${t.version}" data-role="${e(role)}"><label class="check-row"><input type="checkbox" required>I have read and accept version ${t.version}, including the deliverables, reward, deadline, usage rights, review process, and revision rounds.</label><p class="form-hint">This records a role acknowledgment in this browser’s prototype.</p><div class="actions"><button class="button primary">Accept v${t.version} as ${e(role)}</button></div></form>`);}
 if(action==='request-changes'){return openModal('Give clear, actionable feedback.',`<form id="revision-form" data-id="${e(id)}"><label for="revision-note">What needs to change?</label><textarea id="revision-note" name="note" required maxlength="2400" placeholder="Reference an agreed deliverable and explain what would meet it…"></textarea><p class="form-hint">This uses one included revision round. New deliverables or expanded scope should be proposed as an agreement amendment.</p><div class="actions"><button class="button primary">Send revision request ↗</button></div></form>`);}
 if(action==='approve-work'){return openModal('Approve the submitted work?',`<form id="approval-form" data-id="${e(id)}"><p class="modal-intro">Check the linked content and the accepted terms before recording final approval.</p><label class="check-row"><input type="checkbox" required>I reviewed the actual submitted work and it meets the agreed deliverables.</label><p class="form-hint">Approval closes content review. Reward delivery remains a separate step.</p><div class="actions"><button class="button primary">Approve completed work</button></div></form>`);}
 if(action==='new')return newBrief();if(action==='details')return details(id);if(action==='apply')return apply(id);if(action==='submit-work')return submitWork(id);
 if(action==='browse'){navigate('explore');return;}
 if(action==='workspace'||action==='explore'){navigate(action);return;}
 if(action==='save'){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();renderCards();return;}
 if(action==='saved'){navigate(view==='saved'?'explore':'saved');return;}

 if(action==='reward-delivered'){const a=state.applications.find(x=>x.id===id);if(role!=='business'||a.status!=='Approved')return;a.rewardDelivered=true;persist();render();toast('Reward marked as delivered. No payment was sent by LocalPerks.');return;}
 if(action==='review'){const a=state.applications.find(x=>x.id===id),submission=a.submissions.filter(s=>!s.legacy).at(-1),version=a.terms.version;b.disabled=true;b.textContent=aiState.ready?'Reviewing caption…':'Preparing AI…';try{const result=await reviewCaption({deliverables:a.terms.deliverables.split('\n')},submission.caption);const current=state.applications.find(x=>x.id===id);if(current.terms.version!==version||current.submissions.filter(s=>!s.legacy).at(-1)?.id!==submission.id){toast('The agreement or submission changed. Request a fresh review.');return;}current.review=result;persist();render();}catch(err){toast(err.message);b.disabled=false;b.textContent='✧ Review caption with Gemma';}return;}
 if(action==='enable-ai'){b.disabled=true;try{await enableAI();settings();}catch(err){toast(err.message);b.disabled=false;}return;}
 if(action==='export'){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='localperks-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your data downloaded.');return;}
 if(action==='reset'){openModal('Reset this demo workspace?',`<p class="modal-intro">This removes your saved opportunities, applications, and custom briefs from this browser. Download your data first if you want to keep them.</p><div class="actions"><button class="button secondary" data-action="settings">Keep workspace</button><button class="button" data-action="confirm-reset">Reset workspace</button></div>`);return;}
 if(action==='confirm-reset'){state={campaigns:structuredClone(seeds),applications:[],saved:[]};persist();modal.close();render();toast('Sample workspace reset.');}
});
document.addEventListener('input',event=>{if(event.target.id==='search'){search=event.target.value;renderCards();}});
document.addEventListener('change',event=>{if(event.target.id==='city'){city=event.target.value;renderCards();}if(event.target.id==='reward'){reward=event.target.value;renderCards();}});
document.addEventListener('submit',async event=>{
 const f=event.target;if(!['caption-start-form','idea-start-form','caption-check-form','apply-form','brief-form','publish-form','work-form','memory-form','message-form','terms-form','accept-form','revision-form','approval-form'].includes(f.id))return;event.preventDefault();const data=Object.fromEntries(new FormData(f));
 if(f.id==='caption-start-form'){captionCheck(data.idea.trim());return;}
 if(f.id==='idea-start-form'){newBrief(data.idea.trim());return;}
 if(f.id==='caption-check-form'){const button=f.querySelector('button');button.disabled=true;$('#caption-status').textContent='Gemma is reviewing your caption…';$('#caption-result').textContent='';try{const result=await reviewCaption({deliverables:data.deliverables.split('\n').map(x=>x.trim()).filter(Boolean)},data.caption);if(f.isConnected){$('#caption-result').textContent=result;$('#caption-status').textContent='Review ready. Check these suggestions before publishing.';}}catch(err){if(f.isConnected)$('#caption-status').textContent=err.message;}finally{button.disabled=false;}return;}
 if(f.id==='apply-form'){if(ownApplications().some(x=>x.campaignId===f.dataset.id)){toast('An application already exists for this opportunity.');return;}const application=initializeCollaboration({id:crypto.randomUUID(),campaignId:f.dataset.id,...data,status:'Applied',createdAt:new Date().toISOString()});state.applications.push(application);persist();modal.close();roomId=application.id;view='room';render();toast('Proposal sent. Open the conversation and discuss the details.');}
 if(f.id==='brief-form'){const isAI=event.submitter?.value==='ai';const buttons=f.querySelectorAll('button');buttons.forEach(x=>x.disabled=true);$('#brief-status').textContent=isAI?'Drafting your campaign brief with hosted Gemma…':'Preparing the manual template…';try{const result=isAI?await generateBrief(data):{title:`Create with ${data.business}`,description:data.idea,deliverables:[`Create one original ${data.platform} post about your experience at ${data.business}.`,'Agree on content format, usage rights, and posting details before starting.','Clearly disclose the collaboration and any compensation or gifts.'],questions:['Confirm the exact format and length.','Agree on any content usage beyond the original post.']};draft={...data,...result,ai:isAI};editDraft();}catch(err){$('#brief-status').textContent=err.message;$('#brief-status').classList.add('error');buttons.forEach(x=>x.disabled=false);}}
 if(f.id==='publish-form'){const deliverables=data.deliverables.split('\n').map(x=>x.trim()).filter(Boolean);if(!deliverables.length){toast('Add at least one deliverable.');return;}const clarificationAnswers=collectAnswers(draft.questions,data);for(const name of Object.keys(data))if(name.startsWith('answer_'))delete data[name];state.campaigns.unshift({...draft,...data,deliverables,clarificationAnswers,id:crypto.randomUUID(),sample:false,art:draft.category==='Wellness'?'studio':draft.category==='Shops & makers'?'plant':'coffee',color:draft.category==='Wellness'?'#ddd4ee':draft.category==='Shops & makers'?'#d9e8cf':'#efcfad'});persist();modal.close();view='campaigns';category='All';search='';city='All cities';reward='All rewards';savedOnly=false;render();toast('Opportunity added to this demo workspace.');}
 if(f.id==='work-form'){const a=state.applications.find(x=>x.id===f.dataset.id);try{replaceApplication(a.id,recordSubmission(a,role,{url:data.submission,caption:data.caption}));modal.close();render();toast('Work submitted against the accepted agreement.');}catch(err){toast(err.message);}}
 if(['message-form','terms-form','accept-form','revision-form','approval-form'].includes(f.id)){const a=state.applications.find(x=>x.id===f.dataset.id);try{let next;if(f.id==='message-form')next=sendMessage(a,role,data.message);if(f.id==='terms-form')next=proposeTerms(a,role,data);if(f.id==='accept-form'){if(role!==f.dataset.role)throw new Error('The active role changed. Review the agreement again.');next=acceptTerms(a,role,f.dataset.version);}if(f.id==='revision-form')next=requestChanges(a,role,data.note);if(f.id==='approval-form')next=approveWork(a,role);replaceApplication(a.id,next);if(f.id!=='message-form')modal.close();render();toast(f.id==='terms-form'?'New terms proposed. Both sides must accept this version.':f.id==='accept-form'?(agreed(next)?'Both sides agreed. Work can begin.':'Acceptance recorded. Waiting for the other side.') :f.id==='message-form'?'Message sent.':f.id==='revision-form'?'Revision request sent.':'Work approved. Reward delivery is pending.');}catch(err){toast(err.message);}}
 if(f.id==='memory-form'){const c=state.campaigns.find(x=>x.id===data.campaignId),button=f.querySelector('button');button.disabled=true;$('#memory-status').textContent='Asking Backboard…';try{const response=await fetch('/api/memory',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({campaign:c,question:data.question})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Backboard request failed.');$('#memory-result').textContent=result.answer;$('#memory-status').textContent='Campaign memory updated on Backboard.';}catch(err){$('#memory-status').textContent=err.message;}finally{button.disabled=false;}}
});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close();}});
persist();
render();syncSidebar();matchMedia('(max-width:850px)').addEventListener('change',syncSidebar);
document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.body.classList.remove('sidebar-open');syncSidebar();}});
observeAI(s=>{const label=document.querySelector('#global-ai-status');if(label)label.textContent=s.ready?'✧ AI ready':s.failed?'✧ AI unavailable':`✧ Connecting AI${s.progress?' · '+Math.round(s.progress*100)+'%':''}`;const status=document.querySelector('#ai-status');if(status)status.textContent=s.message;const progress=document.querySelector('#ai-progress');if(progress)progress.value=s.progress;const brief=document.querySelector('#brief-ai');if(brief)brief.textContent=s.ready?'✧ AI is ready.':s.failed?s.message:s.message;});
enableAI().catch(()=>{});
fetch('/api/partners').then(r=>r.ok?r.json():null).then(p=>{if(p)partners=p;}).catch(()=>{});
